-- Engineering
insert into public.packs (id, category_id, title, course, description, position) values
  ('eng-circuits', 'engineering', 'Circuit Analysis', 'Circuits I and II', 'Kirchhoff''s laws, dividers, nodal and mesh analysis, Thévenin/Norton, superposition, op-amps, C and L, first- and second-order transients, phasors and impedance, AC power, resonance, filters, transformers and three-phase power.', 0),
  ('eng-statics', 'engineering', 'Statics', 'Engineering Mechanics', 'Force vectors and moments, couples and equivalent systems, FBDs and supports, trusses, frames and machines, beam shear and moment, cables, friction (wedges, screws, belts), centroids, area moments of inertia and virtual work.', 1),
  ('eng-materials', 'engineering', 'Mechanics of Materials', 'Strength of Materials', 'Stress and strain, material properties, axial and thermal loading, indeterminate members, torsion, bending and transverse shear, pressure vessels, combined loads, Mohr''s circle, failure theories, beam deflection and buckling, with worked numbers.', 2),
  ('eng-thermo', 'engineering', 'Engineering Thermodynamics', 'Thermodynamics I', 'Systems and properties, steam tables and quality, ideal gases, boundary work, the first law for closed systems and flow devices, second law and Carnot limits, entropy and isentropic efficiency, exergy, Otto, Diesel, Brayton, Rankine and refrigeration cycles, moist air and combustion basics.', 3),
  ('eng-fluids', 'engineering', 'Fluid Mechanics', 'Fluid Mechanics', 'Viscosity, hydrostatics, buoyancy, center of pressure, continuity, Bernoulli and Pitot tubes, Reynolds number, friction factor, head loss, drag scaling.', 4),
  ('eng-digital-logic', 'engineering', 'Digital Logic', 'Digital Systems', 'Hex and two''s complement, overflow, De Morgan, NAND universality, parity, minterms and K-maps, adders, muxes, latches, flip-flops, timing, FSMs, counters.', 5)
